#!/usr/bin/env python3
"""Generate docs/agents/<name>.md and docs/agents/README.md from agent frontmatter and the role registry.

    python3 scripts/gen_docs.py [--check] [--root PATH]

--check writes nothing and exits 1 if any generated file is missing, different or stale.
Stdlib only. Output is deterministic.
"""

import argparse
import json
import os
import re
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import shipyard_frontmatter as fmlib  # noqa: E402

DEFAULT_ROOT = os.path.normpath(os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))
MARKER = "<!-- Generated by scripts/gen_docs.py from agents/*.md and registry/roles.json. Do not edit by hand. -->"
STAGE_LABEL = {"slice": "Slice review", "plan": "Plan review"}


def first_paragraph(body):
    """First paragraph of prose in the agent body (headings, rules and blank lines skipped)."""
    para = []
    for line in body.splitlines():
        s = line.strip()
        if not s:
            if para:
                break
            continue
        if s.startswith("#") or s in ("---", "***") or s.startswith("<!--"):
            if para:
                break
            continue
        para.append(s)
    return " ".join(para)


def first_sentence(text, min_len=60):
    """Leading sentence(s) of `text`, plain text, at least `min_len` characters when the text allows."""
    plain = re.sub(r"[*_`]", "", text).strip()
    sentences = re.findall(r".+?[.!?](?=\s|$)|.+$", plain)
    out = ""
    for s in sentences:
        out = (out + " " + s.strip()).strip()
        if len(out) >= min_len:
            break
    return out


def role_for(registry, name):
    for role_name, role in (registry.get("roles") or {}).items():
        if role.get("agent") == "shipyard:" + name:
            return role_name, role
    return None, {}


def contract_link(ref):
    stem = ref.split("@", 1)[0]
    return "[`%s`](../../contracts/%s.schema.json)" % (ref, stem)


def contract_for_mode(role, mode):
    per_mode = role.get("contracts") or {}
    if mode in per_mode:
        return per_mode[mode]
    return role.get("contract")


def routing_lines(registry, role_name):
    routing = registry.get("routing") or {}
    defs = routing.get("triggerDefinitions") or {}
    lines = []
    for stage in ("plan", "slice"):
        for rule in routing.get(stage) or []:
            if rule.get("role") != role_name:
                continue
            when = rule.get("when") or []
            if when == ["always"]:
                text = "always"
            else:
                parts = []
                for t in when:
                    parts.append("`%s` (%s)" % (t, defs[t]) if t in defs else "`%s`" % t)
                text = "when any of: " + "; ".join(parts) if parts else "always"
            unless = rule.get("unless") or []
            if unless:
                text += " — unless " + ", ".join("`%s`" % u for u in unless)
            if rule.get("note"):
                text += ". " + rule["note"].rstrip(".") + "."
            lines.append("- **%s:** %s" % (STAGE_LABEL.get(stage, stage), text))
    if lines and routing.get("uncertainFlag") == "route":
        lines.append("- An uncertain trigger counts as set: the reviewer is routed.")
    return lines


def render_agent(name, fm, body, registry):
    role_name, role = role_for(registry, name)
    classes = registry.get("computeClasses") or {}
    out = [MARKER, "", "# %s" % name, ""]
    ident = "`shipyard:%s`" % name
    if role_name:
        ident += " · role `%s`" % role_name
    out += [ident, ""]
    para = first_paragraph(body)
    if para:
        out += [para, ""]

    out += ["## Modes and compute", ""]
    modes = role.get("modes") or {}
    if modes:
        out += ["| Mode | Compute class | Model | Effort | Contract |", "|---|---|---|---|---|"]
        for mode, cls in modes.items():
            spec = classes.get(cls, {})
            ref = contract_for_mode(role, mode)
            out.append("| %s | %s | %s | %s | %s |" % (
                mode, cls, spec.get("model", "?"), spec.get("effort", "?"), contract_link(ref) if ref else "—"))
        out.append("")
    else:
        out += ["Not in the role registry.", ""]
    default = []
    if fm.get("model"):
        default.append("model `%s`" % fm["model"])
    if fm.get("effort"):
        default.append("effort `%s`" % fm["effort"])
    if default:
        out += ["Frontmatter default: %s. Workflows override per mode from the registry." % ", ".join(default), ""]

    refs = []
    for ref in [role.get("contract")] + list((role.get("contracts") or {}).values()):
        if ref and ref not in refs:
            refs.append(ref)
    out += ["## Return contract", ""]
    out += ["- " + contract_link(r) for r in refs] if refs else ["None (this role returns no structured block)."]
    out.append("")

    skills = list(role.get("skills") or [])
    preloaded = fm.get("skills") or []
    if isinstance(preloaded, str):
        preloaded = [preloaded]
    for s in preloaded:
        if s not in skills:
            skills.append(s)
    out += ["## Capability skills", ""]
    if skills:
        for s in skills:
            tag = " (preloaded)" if s in preloaded else ""
            out.append("- [`%s`](../../skills/%s/SKILL.md)%s" % (s, s, tag))
    else:
        out.append("None. This agent works without skills by design.")
    out.append("")

    tools = fmlib.tools_list(fm.get("tools"))
    out += ["## Tools", ""]
    out.append(", ".join("`%s`" % t for t in tools) if tools else "None listed.")
    if fm.get("disallowedTools"):
        out.append("")
        out.append("Disallowed: " + ", ".join("`%s`" % t for t in fmlib.tools_list(fm["disallowedTools"])))
    out.append("")
    out.append("Max turns: %s." % (fm["maxTurns"] if fm.get("maxTurns") else "not set"))
    out.append("")

    out += ["## When it is selected", ""]
    lines = routing_lines(registry, role_name) if role_name else []
    if lines:
        out += lines
    else:
        out.append("Not routed by triggers: the coordinator or a workflow calls it by mode.")
    out += ["", "## Source", "", "[`agents/%s.md`](../../agents/%s.md)" % (name, name), ""]
    return "\n".join(out)


def render_index(entries, registry):
    out = [MARKER, "", "# Agents", "",
           "One page per Shipyard agent, generated from the agent files and `registry/roles.json`.",
           "Run `python3 scripts/gen_docs.py` after changing either.", "",
           "| Agent | Role | Modes | Contract | Summary |", "|---|---|---|---|---|"]
    for name, fm, body in entries:
        role_name, role = role_for(registry, name)
        modes = ", ".join((role.get("modes") or {}).keys()) or "—"
        refs = []
        for ref in [role.get("contract")] + list((role.get("contracts") or {}).values()):
            if ref and ref not in refs:
                refs.append(ref)
        summary = first_sentence(first_paragraph(body)).replace("|", "\\|")
        out.append("| [%s](%s.md) | %s | %s | %s | %s |" % (
            name, name, role_name or "—", modes, ", ".join("`%s`" % r for r in refs) or "—", summary))
    out.append("")
    return "\n".join(out)


def build(root):
    """Return {relative path: content} for every generated file."""
    with open(os.path.join(root, "registry", "roles.json"), encoding="utf-8") as fh:
        registry = json.load(fh)
    adir = os.path.join(root, "agents")
    entries = []
    for fname in sorted(os.listdir(adir)) if os.path.isdir(adir) else []:
        if fname.endswith(".md"):
            fm, body = fmlib.read(os.path.join(adir, fname))
            entries.append((fname[:-3], fm, body))
    files = {}
    for name, fm, body in entries:
        files["docs/agents/%s.md" % name] = render_agent(name, fm, body, registry)
    files["docs/agents/README.md"] = render_index(entries, registry)
    return files


def stale_files(root, files):
    ddir = os.path.join(root, "docs", "agents")
    stale = []
    if os.path.isdir(ddir):
        for fname in sorted(os.listdir(ddir)):
            relpath = "docs/agents/" + fname
            if fname.endswith(".md") and relpath not in files:
                with open(os.path.join(ddir, fname), encoding="utf-8") as fh:
                    if fh.readline().strip() == MARKER:
                        stale.append(relpath)
    return stale


def main(argv=None):
    parser = argparse.ArgumentParser(description="Generate docs/agents/ from agents and the registry")
    parser.add_argument("--check", action="store_true", help="exit 1 if generated docs are out of date")
    parser.add_argument("--root", default=DEFAULT_ROOT)
    args = parser.parse_args(argv)
    root = os.path.abspath(args.root)
    try:
        files = build(root)
    except (OSError, ValueError) as exc:
        sys.stderr.write("gen_docs: %s\n" % exc)
        return 2
    changed = []
    for relpath, content in sorted(files.items()):
        path = os.path.join(root, relpath)
        current = None
        if os.path.isfile(path):
            with open(path, encoding="utf-8") as fh:
                current = fh.read()
        if current != content:
            changed.append(relpath)
            if not args.check:
                os.makedirs(os.path.dirname(path), exist_ok=True)
                with open(path, "w", encoding="utf-8") as fh:
                    fh.write(content)
    stale = stale_files(root, files)
    if not args.check:
        for relpath in stale:
            os.remove(os.path.join(root, relpath))
    if args.check:
        if changed or stale:
            print("gen_docs --check: out of date. Run `python3 scripts/gen_docs.py`.")
            for c in changed:
                print("  would write " + c)
            for s in stale:
                print("  would remove " + s)
            return 1
        print("gen_docs --check: up to date (%d files)" % len(files))
        return 0
    print("gen_docs: %d written, %d removed, %d unchanged" % (len(changed), len(stale), len(files) - len(changed)))
    return 0


if __name__ == "__main__":
    sys.exit(main())
